window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-772a75b2cdde45ce"]={"versions": [{"id": "FIG-772a75b2cdde45ce", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Sequenzdiagramm für die Übertragungsart DIRECT (N-Times) im AUTOSAR Communication Modul (<code>AUTOSAR_SWS_COM</code>). Das Diagramm illustriert das zeitliche Verhalten von ereignisgesteuerten I-PDU- bzw. Signal-Übertragungen über einer horizontalen Zeitachse t für den Wiederholungszähler n = 3 ohne Umschaltung des Transmission Mode Selectors (TMS).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sendeanforderung (<code>v := x</code>)</strong>: Software-Trigger / COM-API-Aufruf zur Signalaktualisierung (symbolisiert durch ein Blitzsymbol).\n</li><li><strong>Sendezeitpunkte (grüne Pfeile)</strong>: Ausgehende I-PDU-Transmissionsimpulse über die unterlagerte Schicht (PduR / Bus-Schnittstelle).\n</li><li><strong>Abgebrochene / verschobene Sendezeitpunkte (blaue Pfeile)</strong>: Ursprünglich geplante Sendeimpulse, die durch eine zwischenzeitliche Neuübertragung bzw. Re-Triggerung beeinflusst werden.\n</li><li><strong>Zeitparameter</strong>:\n<ul class=\"fig-list\"><li>t_d: Konfiguriertes Wiederholungsintervall zwischen aufeinanderfolgenden N-Times-Aussendungen (<code>ComTxIPduNumberOfRepetitions</code> / <code>ComTxIPduRepetitionPeriod</code>).\n</li><li>$t_{r,\\min}$: Minimale Reaktionszeit bzw. Verzögerung zwischen Auslöseereignis und erster PDU-Aussendung.\n</li><li>dt: Mindestabstand bzw. Filterzeit (<code>ComTxIPduMinDelayTime</code>) zwischen Übertragungen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Dargestellt sind drei aufeinanderfolgende Sequenzszenarien für n = 3:</p>\n<ol class=\"fig-list\"><li><strong>Reguläre N-Times-Folge</strong>: Nach Auslösung (<code>v := x</code>) erfolgt nach $t_{r,\\min}$ die erste Aussendung, gefolgt von zwei weiteren Aussendungen im konstanten Abstand t_d (insgesamt 3 Übertragungen).\n</li><li><strong>Re-Triggerung außerhalb des Mindestabstands</strong>: Nach der ersten Aussendung erfolgt ein zweiter Aufruf <code>v := x</code> nach Ablauf von dt. Die laufende Wiederholungssequenz wird neu gestartet: Der nächste Sendezeitpunkt erfolgt planmäßig nach Ablauf des Intervalls t_d, woraufhin erneut 3 vollständige Aussendungen im Abstand t_d folgen.\n</li><li><strong>Re-Triggerung innerhalb des Mindestabstands</strong>: Ein zweiter Trigger trifft unmittelbar vor Ablauf von dt ein. Die Aussendung muss verzögert werden, bis die Mindestverzögerungszeit dt abgelaufen ist; anschließend wird die N-Times-Sequenz von 3 Aussendungen im Intervall t_d abgearbeitet.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die normative Implementierung der N-Times-Übertragung nach SWS COM:</p>\n<ul class=\"fig-list\"><li>Jeder Übertragungsaufruf initiiert eine Serie von genau n Wiederholungen mit dem Intervall t_d.\n</li><li>Trifft während einer laufenden N-Times-Sequenz eine neue Sendeanforderung für dieselbe I-PDU ein, wird der Wiederholungszähler neu auf n gesetzt (Re-Triggerung).\n</li><li>Die Einhaltung des Mindestsendeabstands (<code>ComTxIPduMinDelayTime</code> / dt) hat Vorrang vor der sofortigen Aussendung; ein neuer Sendeimpuls darf frühestens nach Ablauf von dt erfolgen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6e95b777e16d061b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Sequenzdiagramm für die Übertragungsart DIRECT (N-Times) im AUTOSAR Communication Modul (<code>AUTOSAR_SWS_COM</code>). Das Diagramm illustriert das zeitliche Verhalten von ereignisgesteuerten I-PDU- bzw. Signal-Übertragungen über einer horizontalen Zeitachse t für den Wiederholungszähler n = 3 ohne Umschaltung des Transmission Mode Selectors (TMS).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Sendeanforderung (<code>v := x</code>)</strong>: Software-Trigger / COM-API-Aufruf zur Signalaktualisierung (symbolisiert durch rote Dreiecksymbole auf der Zeitachse).\n</li><li><strong>Sendezeitpunkte (grüne Pfeile)</strong>: Reguläre PDU-Aussendungen an die unterlagerte Schnittstelle.\n</li><li><strong>Verzögerte / ersetzte Sendezeitpunkte (blaue Pfeile)</strong>: Durch Übertragungsabstände oder Re-Triggerung modifizierte Sendezeitpunkte.\n</li><li><strong>Zeitparameter</strong>:\n<ul class=\"fig-list\"><li>t_d: Wiederholungsperiode zwischen den n Übertragungen (<code>ComTxIPduRepetitionPeriod</code>).\n</li><li>t_r bzw. t_r_1: Reaktionszeit zwischen Trigger und Start der Übertragung.\n</li><li>dt: Mindestzeitabstand (<code>ComTxIPduMinDelayTime</code>) zwischen aufeinanderfolgenden Übertragungen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Dargestellt sind drei Sequenzszenarien für n = 3:</p>\n<ol class=\"fig-list\"><li><strong>Reguläre N-Times-Folge</strong>: Auslösung durch <code>v := x</code>, erste Aussendung nach Reaktionszeit t_r, gefolgt von zwei Wiederholungen im zeitlichen Abstand t_d.\n</li><li><strong>Re-Triggerung nach Ablauf des Mindestzeitabstands</strong>: Ein zweiter Trigger <code>v := x</code> trifft nach Ablauf von dt ein. Die Sequenz wird re-triggert, sodass ab dem nächsten Übertragungsschritt t_d erneut eine vollständige Folge von 3 Aussendungen im Abstand t_d abgesetzt wird.\n</li><li><strong>Re-Triggerung vor Ablauf des Mindestzeitabstands</strong>: Zwei zeitlich dicht aufeinanderfolgende Trigger <code>v := x</code> führen dazu, dass die Aussendung des zweiten Zyklus durch dt blockiert wird. Die Folge startet erst nach Ablauf von dt, gefolgt von den weiteren Wiederholungen im Intervall t_d.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die normative Implementierung der N-Times-Übertragung nach SWS COM:</p>\n<ul class=\"fig-list\"><li>Jeder Übertragungsaufruf initiiert eine Serie von genau n Wiederholungen mit dem Intervall t_d.\n</li><li>Trifft während einer laufenden N-Times-Sequenz eine neue Sendeanforderung für dieselbe I-PDU ein, wird der Wiederholungszähler neu auf n gesetzt (Re-Triggerung).\n</li><li>Die Einhaltung des Mindestsendeabstands (<code>ComTxIPduMinDelayTime</code> / dt) hat Vorrang vor der sofortigen Aussendung; ein neuer Sendeimpuls darf frühestens nach Ablauf von dt erfolgen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-772a75b2cdde45ce", "to": "FIG-6e95b777e16d061b", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Ereignis-Symbolik</strong>: Sendeanforderungen durch oberen Software-Aufruf (<code>v := x</code>) werden nicht mehr als orangefarbene Blitzsymbole, sondern als rote Dreiecke dargestellt.\n</li><li><strong>Benennung der Reaktionszeit</strong>: Die Latenz bis zur ersten Übertragung wird von $t_{r,\\min}$ zu t_r bzw. t_r_1 umbenannt; die grafische Auszeichnung erfolgt über geschwungene Klammern statt horizontaler Pfeile.\n</li><li><strong>Intervall-Auszeichnung</strong>: Die minimale Sendeabstandszeit bzw. Latenz (dt) wird nun mit Klammern unterhalb der Zeitachse dargestellt.\n</li><li><strong>Darstellung der zweiten Sendeanforderung im dritten Szenario</strong>: Der erneute Aufruf <code>v := x</code> ist explizit als eigenes rotes Dreieck visualisiert (im vorherigen Diagramm durch einen zweiten Blitz überlappend angedeutet).\n</li></ul>"}]};
